'use strict';
// Local vector digital twins. Telemetry is simulated; no external models or textures.
let twinSelectedRack = 12;
let twinHall = 'A';
let twinSerial = 0;
function twinRackReading(n) {
  const alertHall = twinHall === 'A' && currentSite().id === 'cairo' && state.building === 'DC-01';
  const hot = alertHall && n === 12;
  const warm = alertHall && n === 21;
  return {n, hot, warm, temperature: hot ? 32.8 : warm ? 28.1 : +(22.1 + (n * 7 % 25) / 10).toFixed(1), load: hot ? 82 : 54 + n * 11 % 38, power: +(3.2 + n * 7 % 31 / 10).toFixed(1), humidity: 44 + n % 5};
}
function twinRackSVG(n, full = false) {
  const r = twinRackReading(n), id = `rack-${++twinSerial}`, color = r.hot ? '#ff747b' : r.warm ? '#edbc64' : '#25e3c2';
  return `<svg class="rack-model ${full ? 'full-rack' : ''}" viewBox="0 0 170 ${full ? 284 : 122}" aria-hidden="true"><defs>
    <linearGradient id="${id}-metal"><stop stop-color="#0b0f12"/><stop offset=".12" stop-color="#6e7c83"/><stop offset=".24" stop-color="#263139"/><stop offset=".8" stop-color="#0c1217"/><stop offset=".94" stop-color="#728188"/><stop offset="1" stop-color="#202b30"/></linearGradient>
    <linearGradient id="${id}-server" x2="0" y2="1"><stop stop-color="#4b575d"/><stop offset=".14" stop-color="#253139"/><stop offset=".5" stop-color="#0d151a"/><stop offset=".92" stop-color="#1d292f"/><stop offset="1" stop-color="#68767a"/></linearGradient>
    <pattern id="${id}-mesh" width="3" height="3" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".58" fill="#73818a" opacity=".45"/></pattern>
    <radialGradient id="${id}-glow"><stop stop-color="${color}" stop-opacity=".3"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></radialGradient>
    </defs><ellipse cx="85" cy="${full ? 273 : 116}" rx="76" ry="8" fill="#000" opacity=".6"/>
    <path d="M12 6 158 6 164 12V${full ? 267 : 130}H8V12Z" fill="#070b0e" stroke="#53636e"/>
    <rect x="13" y="9" width="145" height="${full ? 255 : 120}" rx="3" fill="url(#${id}-metal)" stroke="#8d9a9f" stroke-opacity=".5"/>
    <rect x="24" y="17" width="122" height="${full ? 238 : 111}" fill="#060b0f" stroke="#414d54"/>
    <rect x="29" y="20" width="112" height="${full ? 229 : 109}" fill="url(#${id}-mesh)"/>
    ${Array.from({length: full ? 16 : 7}, (_, i) => {const y = 30 + i * (full ? 13.2 : 13.7);return `<g><rect x="34" y="${y}" width="103" height="11" rx="1" fill="url(#${id}-server)" stroke="#536269" stroke-width=".45"/><rect x="40" y="${y+3}" width="51" height="5" rx="1" fill="#071015"/>${Array.from({length:10},(_,j)=>`<path d="M${42+j*4.5} ${y+4}v3" stroke="#7c8b91" stroke-opacity=".6" stroke-width=".7"/>`).join('')}<rect x="96" y="${y+3}" width="16" height="5" fill="#121b1f" stroke="#6a797d" stroke-width=".4"/><circle cx="120" cy="${y+5.5}" r="1.4" fill="#80cf5b"/><circle cx="126" cy="${y+5.5}" r="1.2" fill="${i%3?'#81c64b':'#e8c778'}"/><rect x="35" y="${y+2}" width="2" height="7" fill="#86979b"/><rect x="133" y="${y+2}" width="2" height="7" fill="#86979b"/></g>`}).join('')}
    <rect x="19" y="41" width="4" height="39" rx="2" fill="#a8b4b6"/><rect x="20" y="45" width="2" height="31" fill="#354147"/>
    ${[18,151].map(x=>[15,full?256:114].map(y=>`<circle cx="${x}" cy="${y}" r="1.4" fill="#a8b6bb"/><path d="M${x-1} ${y}h2" stroke="#172027" stroke-width=".6"/>`).join('')).join('')}
    <circle cx="148" cy="16" r="10" fill="url(#${id}-glow)"/><circle cx="148" cy="16" r="3.5" fill="${color}"/>
    ${state.heatmap?`<rect x="24" y="17" width="122" height="${full?238:111}" fill="${color}" opacity=".26"/>`:''}</svg>`;
}
function twinRackDetail() {
  const r = twinRackReading(twinSelectedRack), name = `R-${String(r.n).padStart(2,'0')}`;
  return `<button class="rack-inspector" data-equipment="Rack ${name}" aria-label="Inspect rack ${name}">${twinRackSVG(r.n,true)}<div><h3>Rack ${name}</h3><span class="twin-status ${r.hot?'hot':r.warm?'warm':''}">${r.hot?'High inlet temperature':r.warm?'Temperature advisory':'Operating normally'}</span><dl><div><dt>Inlet temperature</dt><dd class="${r.hot?'negative':''}">${r.temperature.toFixed(1)} °C</dd></div><div><dt>Rack load</dt><dd>${r.load} %</dd></div><div><dt>Power draw</dt><dd>${r.power.toFixed(1)} kW</dd></div></dl><small>Open asset inspector ↗</small></div></button>`;
}
dataHalls = function() {
  const rackData = Array.from({length:32},(_,i)=>twinRackReading(i+1));
  const maximum = Math.max(...rackData.map(r=>r.temperature));
  const mean = (rackData.reduce((v,r)=>v+r.temperature,0)/32).toFixed(1);
  const hot = rackData.find(r=>r.hot);
  return buildingKPIs()+`<div class="white-space-layout">${panel(`Data Hall ${twinHall} · Rack layout`,'Select any rack to inspect its environment and load.',`<div class="rack-grid twin-rack-grid ${state.heatmap?'thermal-active':''}">${rackData.map((r,i)=>`${i===16?'<div class="rack-aisle"><span>COLD AISLE / CONTAINMENT</span></div>':''}<button class="rack-tile ${r.hot?'critical':r.warm?'warning':''} ${r.n===twinSelectedRack?'selected':''}" data-rack-select="${r.n}" aria-pressed="${r.n===twinSelectedRack}" aria-label="Rack R-${String(r.n).padStart(2,'0')}, ${r.temperature.toFixed(1)} degrees Celsius, ${r.load} percent load"><div class="rack-crop">${twinRackSVG(r.n)}${r.hot||state.heatmap?`<span class="rack-temperature">${r.temperature.toFixed(1)}°C</span>`:''}</div><span class="rack-name">R-${String(r.n).padStart(2,'0')}</span></button>`).join('')}</div>`,`<div class="hall-switch" role="group" aria-label="Select data hall">${['A','B'].map(h=>`<button data-hall-select="${h}" aria-pressed="${twinHall===h}">Hall ${h}</button>`).join('')}</div><button class="heatmap-toggle" data-action="heatmap" aria-pressed="${state.heatmap}">${state.heatmap?'Hide':'Show'} thermal overlay</button>`,'white-space-panel')}${panel('White space conditions','Current data hall readings',`<div class="detail-list"><p>Average inlet<strong>${mean} °C</strong></p><p>Maximum inlet<strong class="${hot?'negative':''}">${maximum.toFixed(1)} °C${hot?' · R-12':''}</strong></p><p>Relative humidity<strong>46 %RH</strong></p><p>Cold aisle differential<strong>9.2 °C</strong></p><p>Cooling units<strong>4 / 4 available</strong></p><p>Containment<strong>Sealed</strong></p><p>Water leak detection<strong>Clear</strong></p></div><div id="rack-detail" aria-live="polite">${twinRackDetail()}</div>`,'','white-space-conditions')}</div><div class="bottom-grid">${panel('Temperature trend','Simulated average and maximum inlet',`<div class="chart-body">${lineChart(2,'temperature')}</div>`)}${panel('Rack capacity','Current occupied rack positions',`<div class="donut-wrap">${donut(currentSite().racks,'Occupied')}<div class="donut-key"><p>Occupied <b>${Math.round(32*currentSite().racks/100)}</b></p><p>Available <b>${32-Math.round(32*currentSite().racks/100)}</b></p></div></div>`)}${panel('Hall alarms',`Data Hall ${twinHall}`,hot?`<div class="mini-alert"><span class="alert-icon">!</span><div><strong>R-12 high inlet temperature</strong><p>32.8 °C · threshold 30 °C<br>Inspect containment and cooling supply.</p></div></div><button class="text-button" data-equipment="Rack R-12">Inspect rack ↗</button>`:'<div class="mini-alert"><span class="chip green">Normal</span><p>All rack inlet temperatures are within range.</p></div>')}</div>`;
};
// Shared three-face cabinet construction with inset doors, vents and controls.
function twinCabinet(x,y,w,h,d=20,kind='cabinet',accent='#2be4be') {
  const vents = Array.from({length:8},(_,i)=>`<path d="M${x+9} ${y+h-13-i*5}h${w-18}" stroke="#111b21" stroke-width="2"/><path d="M${x+9} ${y+h-12-i*5}h${w-18}" stroke="#75848d" stroke-opacity=".3"/>`).join('');
  return `<g><path d="M${x} ${y}l${d} ${-d*.6}h${w}l${-d} ${d*.6}Z" fill="#687984" stroke="#81929b" stroke-width=".6"/><path d="M${x+w} ${y}l${d} ${-d*.6}v${h}l${-d} ${d*.6}Z" fill="#18252d" stroke="#4c626e" stroke-width=".6"/><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="2" fill="url(#twin-steel)" stroke="#71818b" stroke-width=".7"/><rect x="${x+5}" y="${y+5}" width="${w-10}" height="${h-10}" rx="1" fill="#263740" stroke="#536872" stroke-width=".5"/>${vents}<rect x="${x+10}" y="${y+12}" width="${w-20}" height="22" rx="2" fill="#09151c" stroke="#587682"/><path d="M${x+14} ${y+27}h6l3-7 4 10 3-6h${Math.max(1,w-44)}" stroke="${accent}" fill="none" stroke-width="1"/><circle cx="${x+w-10}" cy="${y+42}" r="2" fill="${accent}"/><rect x="${x+w-11}" y="${y+h*.53}" width="3" height="15" rx="1" fill="#a0afb4"/><text x="${x+w/2}" y="${y+h-3}" fill="#bdced7" font-size="5" text-anchor="middle">${esc(kind.toUpperCase())}</text></g>`;
}
function twinFan(x,y,r=25) {
  return `<g class="twin-fan" style="transform-origin:${x}px ${y}px"><circle cx="${x}" cy="${y}" r="${r}" fill="#101c24" stroke="#7b939e" stroke-width="2"/>${[0,90,180,270].map(a=>`<path d="M${x} ${y}c${-r*.8} ${-r*.9} ${r*.6} ${-r*1.25} ${r*.56} ${-r*.5}L${x} ${y}Z" fill="#657f8b" stroke="#8ba1aa" stroke-width=".5" transform="rotate(${a} ${x} ${y})"/>`).join('')}<circle cx="${x}" cy="${y}" r="${r*.19}" fill="#b0bfc5"/></g><circle cx="${x}" cy="${y}" r="${r+3}" fill="none" stroke="#365461"/>`;
}
function twinCylinder(x,y,r,h,color='#b83c43') {
  return `<path d="M${x-r} ${y}v${h}a${r} ${r*.38} 0 0 0 ${r*2} 0V${y}Z" fill="${color}" stroke="#aeafb0" stroke-width=".5"/><ellipse cx="${x}" cy="${y}" rx="${r}" ry="${r*.38}" fill="#98a8ae"/><path d="M${x-r*.4} ${y+6}v${h-10}" stroke="#fff" stroke-width="3" opacity=".15"/><rect x="${x-4}" y="${y-10}" width="8" height="10" fill="#bfa574"/><path d="M${x} ${y-10}v-8h12" fill="none" stroke="#bc9d5c" stroke-width="3"/><rect x="${x-r+2}" y="${y+h*.45}" width="${r*2-4}" height="12" fill="#d0d7d7"/><text x="${x}" y="${y+h*.45+8}" fill="#333" font-size="5" text-anchor="middle">CLEAN AGENT</text>`;
}
function twinAssetModel(kind) {
  switch(kind) {
    case 'cooling': return `${twinCabinet(110,105,215,110,40,'AHU-03')}<rect x="126" y="121" width="73" height="74" fill="#13252e" stroke="#6f8792"/>${twinFan(162,158,29)}<rect x="211" y="121" width="97" height="74" fill="#152a34" stroke="#6f8792"/>${Array.from({length:13},(_,i)=>`<path d="M${218+i*6} 127v61" stroke="${i%2?'#658f9d':'#94bac4'}" stroke-width="2"/>`).join('')}<path d="M252 207v27h99v-87M269 207v14h66v-81" fill="none" stroke="#42a9c7" stroke-width="5"/><path class="twin-flow" d="M29 160H98M365 160h61" stroke="#48e2d2" stroke-width="4" stroke-dasharray="8 9"/><text x="28" y="140" fill="#6fcce1" font-size="9">18.2 °C SUPPLY</text><text x="350" y="140" fill="#ff8b82" font-size="9">29.4 °C RETURN</text><circle cx="341" cy="116" r="8" fill="#612c35" stroke="#ff777e"/><text x="341" y="119" fill="#fff" font-size="8" text-anchor="middle">!</text>`;
    case 'power': return `${twinCabinet(65,99,61,126,22,'UPS-A')}${twinCabinet(151,99,61,126,22,'UPS-B','#ecbd6d')}${twinCabinet(245,112,70,113,24,'ATS')}${twinCabinet(347,99,52,126,20,'PDU')}<path d="M95 88v-20h279v20M180 88V68M280 101V68" stroke="#e8ba68" stroke-width="4" fill="none"/><path class="twin-flow" d="M95 88v-20h279v20" stroke="#fff2be" stroke-width="1.5" fill="none" stroke-dasharray="4 13"/><text x="235" y="52" text-anchor="middle" fill="#c8dbe2" font-size="9">DUAL FEED / N+1 REDUNDANCY</text>`;
    case 'generator': return `<path d="M90 224l35-19h254l-34 19Z" fill="#0c151b"/><path d="M97 112l39-24h229l-39 24Z" fill="#667c71"/><path d="M326 112l39-24v113l-39 23Z" fill="#243d36"/><rect x="97" y="112" width="229" height="112" rx="3" fill="#476056" stroke="#859b8c"/><rect x="112" y="125" width="111" height="84" fill="#344a42" stroke="#76877c"/>${Array.from({length:11},(_,i)=>`<path d="M120 ${132+i*6}h95" stroke="#172e27" stroke-width="3"/>`).join('')}<rect x="234" y="124" width="78" height="87" fill="#253d34" stroke="#7b9286"/><rect x="245" y="135" width="39" height="23" fill="#0e2021" stroke="#8fa79f"/><path d="M250 148h7l4-6 5 10 4-6h9" stroke="#7de1b6" fill="none"/><circle cx="300" cy="171" r="5" fill="#c14d44"/><path d="M157 97V62h56" stroke="#59696d" stroke-width="11" fill="none"/><path d="M164 64h45" stroke="#b0b8b5" stroke-width="2"/><text x="269" y="195" fill="#cfdfd0" font-size="8" text-anchor="middle">DIESEL · STANDBY</text>`;
    case 'water': return `${twinCylinder(185,101,66,112,'#4e7b8a')}<ellipse cx="185" cy="101" rx="66" ry="25" fill="#a2b6be"/><path d="M185 78v-13h65v125h69" fill="none" stroke="#53afca" stroke-width="7"/><rect x="145" y="132" width="11" height="61" fill="#142934" stroke="#86a7b4"/><rect x="147" y="141" width="7" height="50" fill="#46d2e3"/><circle cx="291" cy="190" r="18" fill="#415d70" stroke="#8eafc0"/><circle cx="291" cy="190" r="8" fill="#20c7c5"/><path d="M273 210h44v10h-44Z" fill="#657d8a"/><text x="185" y="166" fill="#e0f8ff" font-size="17" text-anchor="middle">86%</text>`;
    case 'fire': return `${[139,177,215,253].map(x=>twinCylinder(x,118,14,96)).join('')}<path d="M139 98h126v-25h58" stroke="#be5459" stroke-width="6" fill="none"/>${twinCabinet(310,96,55,119,18,'FACP')}<rect x="318" y="106" width="39" height="28" fill="#063e36" stroke="#69baa4"/><text x="337" y="123" fill="#78e8c6" font-size="7" text-anchor="middle">NORMAL</text><path d="M101 226h173" stroke="#7b8b94" stroke-width="6"/><text x="195" y="62" fill="#ccdae0" font-size="9" text-anchor="middle">CLEAN AGENT SUPPRESSION</text>`;
    case 'security': return `<path d="M115 228V80h134v148" stroke="#59727c" stroke-width="9" fill="none"/><path d="M122 223V88h119v135" fill="#1c3542" stroke="#7d9ca8"/><path d="M130 95h103v122H130Z" fill="#284a58" opacity=".6"/><path d="M135 199l87-93M150 213l77-83" stroke="#7aa5b5" opacity=".3"/><rect x="229" y="137" width="6" height="28" fill="#9cbbc7"/><rect x="267" y="133" width="20" height="31" rx="3" fill="#132d32" stroke="#698f9b"/><path d="M272 146h10m-10 5h10" stroke="#3bebc4"/><path d="M320 95V68h-39" stroke="#7f969e" stroke-width="5"/><path d="M264 56l53 11-8 23-53-11Z" fill="#9fadb4" stroke="#dce3e5"/><ellipse cx="260" cy="68" rx="9" ry="12" fill="#152c39" stroke="#7f9ca9"/><circle cx="260" cy="68" r="4" fill="#28e1c2"/><path d="M251 76 159 215 289 220Z" fill="#58d8cb" opacity=".07"/>`;
    case 'control': return `<path d="M80 222l43-26h226l-45 26Z" fill="#354b57" stroke="#80949c"/><path d="M90 224v24m205-24v24" stroke="#68828f" stroke-width="7"/>${[105,182,259].map((x,i)=>`<rect x="${x}" y="114" width="70" height="67" rx="3" fill="#0b171d" stroke="#718e9b"/><rect x="${x+5}" y="120" width="60" height="50" fill="#14313b"/><path d="M${x+9} 155h8l6-16 10 13 7-20 10 16h10" stroke="${i===1?'#80b2f3':'#4de4bd'}" fill="none"/><path d="M${x+34} 181v17" stroke="#718e9b" stroke-width="5"/>`).join('')}<path d="M135 98h171" stroke="#6e94a0"/><circle cx="135" cy="98" r="3" fill="#4ae7c6"/><text x="222" y="78" text-anchor="middle" fill="#aac6d2" font-size="10">BUILDING MANAGEMENT / FMS</text>`;
    default: return `${twinCabinet(110,82,80,147,25,'NETWORK')}${twinCabinet(236,82,80,147,25,'CONTROL')}`;
  }
}
function twinScene(kind, label, compact=false) {
  return `<svg class="twin-scene ${compact?'compact':''}" viewBox="0 0 460 280" role="img" aria-label="${esc(label)} — three-dimensional equipment visualization"><defs><linearGradient id="twin-steel" x2="1" y2="1"><stop stop-color="#7c8b93"/><stop offset=".15" stop-color="#3a4b56"/><stop offset="1" stop-color="#1c2c36"/></linearGradient><radialGradient id="twin-floor"><stop stop-color="#25434d"/><stop offset="1" stop-color="#111d25"/></radialGradient><pattern id="twin-grid" width="32" height="18" patternUnits="userSpaceOnUse" patternTransform="skewX(-32)"><path d="M32 0H0V18" stroke="#44616d" stroke-width=".5" fill="none"/></pattern></defs><ellipse cx="232" cy="229" rx="211" ry="45" fill="url(#twin-floor)"/><path d="M20 205 106 159H418L452 235 346 275H96Z" fill="url(#twin-grid)" opacity=".4"/><ellipse cx="238" cy="230" rx="152" ry="15" fill="#03090d" opacity=".45"/>${twinAssetModel(kind)}<path d="M23 27v-9h9M428 18h9v9M23 252v9h9M428 261h9v-9" fill="none" stroke="#45636e"/><text x="31" y="34" fill="#698d9e" font-size="7" letter-spacing="2">3D ASSET VIEW</text><circle cx="378" cy="30" r="2" fill="#37d9be"/><text x="386" y="33" fill="#77a99f" font-size="7">SIMULATED</text></svg>`;
}
function twinKind(name) {
  if(/generator|fuel/i.test(name))return 'generator';
  if(/water|tank|pump/i.test(name))return 'water';
  if(/fire|suppression|detector/i.test(name))return 'fire';
  if(/security|entry|door|gate|camera/i.test(name))return 'security';
  if(/ahu|cool|fan|filter|coil|air handling/i.test(name))return 'cooling';
  if(/ups|power|switch|batter|utility|pdu/i.test(name))return 'power';
  if(/control|bms/i.test(name))return 'control';
  return 'network';
}
equipmentCard = function(title,value,unit,description,asset) {
  return `<section class="panel equipment-card twin-equipment-card"><div class="twin-equipment-heading"><h3>${title}</h3><span class="chip green">Monitored</span></div><button class="twin-model-button" data-equipment="${esc(asset)}" aria-label="Inspect ${esc(asset)}">${twinScene(twinKind(asset),asset,true)}</button><div class="reading">${value} <small>${unit}</small></div><p>${description}</p><button class="text-button" data-equipment="${esc(asset)}">Inspect equipment ↗</button></section>`;
};
const twinOriginalMechanical = mechanical, twinOriginalElectrical = electrical, twinOriginalFire = fire, twinOriginalSecurity = security;
mechanical = function(){return twinOriginalMechanical().replace(/<svg class="floorplan"[\s\S]*?<\/svg>/, `<button class="twin-model-button twin-main-model" data-equipment="AHU-03" aria-label="Inspect air handling unit AHU-03">${twinScene('cooling','AHU-03 air handling unit')}</button>`)+`<div class="metric-grid">${equipmentCard('Precision cooling','18.2','°C supply','Fan, filter, and cooling coil assembly.','Supply fan')}${equipmentCard('Chilled water','3.2','bar','Closed circuit pressure and storage availability.','Water tank')}${equipmentCard('Return air','29.4','°C','AHU-03 sensor above the 28 °C threshold.','AHU-03')}</div>`};
electrical = function(){return twinOriginalElectrical().replace(/<svg class="floorplan"[\s\S]*?<\/svg>/,`<button class="twin-model-button twin-main-model" data-equipment="UPS-B" aria-label="Inspect power distribution">${twinScene('power','UPS and power distribution')}</button>`)+`<div class="metric-grid">${equipmentCard('Backup generation','100','% ready','Automatic standby generation; diesel at 74%.','Generator A')}${equipmentCard('UPS bank B','76','% battery health','Capacity inspection recommended.','UPS-B')}${equipmentCard('Switchgear','3.20','MW','Incoming utility and automatic transfer equipment.','Switchgear')}</div>`};
fire = function(){return twinOriginalFire()+`<div class="metric-grid">${equipmentCard('Suppression bank','Ready','','Clean agent cylinders and manifold pressure monitored.','Suppression bank')}${equipmentCard('Fire pump','8.2','bar','Standby duty pump and header pressure.','Fire pump')}${equipmentCard('Emergency access','Clear','','Exit doors and access controllers monitored.','Emergency door')}</div>`};
// Building overview becomes a selectable set of equipment twins instead of empty rectangles.
floorPlan = function(mode='bms') {
  const assets = mode==='fire' ? [['Suppression bank','fire'],['Fire pump','water'],['Fire zone 2','fire'],['Emergency door','security']] : [['Generator A','generator'],['UPS-B','power'],['AHU-03','cooling'],['Switchgear','power'],['Water tank','water'],['Control room','control']];
  return `<div class="twin-floor-grid">${assets.map(([name,kind])=>`<button class="twin-floor-asset" data-equipment="${name}">${twinScene(kind,name,true)}<span>${name}<small>${/AHU/.test(name)?'Temperature alert':/UPS/.test(name)?'Battery advisory':'System available'}</small></span><i class="${/AHU/.test(name)?'hot':/UPS/.test(name)?'warm':''}"></i></button>`).join('')}<div class="twin-hall-entries"><button data-tab="halls">Data Hall A <span>32 rack positions ↗</span></button><button data-open-hall="B">Data Hall B <span>32 rack positions ↗</span></button></div></div>`;
};
cameraScene = function(i) {
  const gate = i===3, corridor = i===4;
  return `<svg viewBox="0 0 400 220" role="img" aria-label="Simulated ${gate?'entry gate':corridor?'control room corridor':'server aisle'} camera scene"><defs><linearGradient id="cam-floor-${i}" x2="0" y2="1"><stop stop-color="#17252c"/><stop offset="1" stop-color="#465d65"/></linearGradient></defs><rect width="400" height="220" fill="#15232c"/><path d="M0 220 158 56h84L400 220Z" fill="url(#cam-floor-${i})"/><path d="M0 0 158 56v164H0ZM400 0 242 56v164h158Z" fill="#20323b"/><path d="M0 0 158 56h84L400 0Z" fill="#2b3c44"/>${[0,1,2,3,4].map(j=>`<path d="M${j*33} 0l${158-j*33} 56M${400-j*33} 0l${242-(400-j*33)} 56" stroke="#4a606b" opacity=".5"/><path d="M${140-j*45} 220 183 56M${260+j*45} 220 217 56" stroke="#6c8188" opacity=".3"/>`).join('')}${!gate&&!corridor?Array.from({length:6},(_,j)=>{const x=j*24,y=j*6,s=1-j*.1;return `<g transform="translate(${x} ${y}) scale(${s})"><rect x="0" y="16" width="34" height="196" fill="#0b1319" stroke="#607078"/>${Array.from({length:12},(_,k)=>`<rect x="4" y="${25+k*14}" width="26" height="10" fill="#263840" stroke="#425963" stroke-width=".5"/><circle cx="25" cy="${30+k*14}" r="1" fill="#75ce60"/>`).join('')}</g><g transform="translate(${400-x} ${y}) scale(${-s} ${s})"><rect x="0" y="16" width="34" height="196" fill="#0b1319" stroke="#607078"/>${Array.from({length:12},(_,k)=>`<rect x="4" y="${25+k*14}" width="26" height="10" fill="#263840"/><circle cx="25" cy="${30+k*14}" r="1" fill="#75ce60"/>`).join('')}</g>`}).join(''):gate?'<path d="M80 170h240" stroke="#d0d6cd" stroke-width="8"/><path d="M90 170h22m18 0h22m18 0h22m18 0h22m18 0h22m18 0h22" stroke="#d85853" stroke-width="8"/><rect x="69" y="147" width="17" height="65" fill="#607982"/><rect x="312" y="147" width="17" height="65" fill="#607982"/><path d="M178 220v-40h44v40" fill="#314f5b" stroke="#92a8af"/>':Array.from({length:3},(_,j)=>`<path d="M${20+j*41} ${40+j*9}v136l27-18V${52+j*9}Z" fill="#132a35" stroke="#587987"/><rect x="${23+j*41}" y="${88+j*7}" width="4" height="8" fill="#39d9bc"/>`).join('')}<path d="M181 21h38m-33 17h28m-24 12h20" stroke="#d9e9e9" stroke-width="4"/><text x="14" y="207" fill="#b3c6c9" font-family="monospace" font-size="8">SIMULATED SCENE · CAM-0${i+1}</text></svg>`;
};
security = function(){return twinOriginalSecurity().replace('Illustrative placeholders � No live CCTV connected','Simulated 3D scenes · No live CCTV connected').replaceAll('Local vector placeholder','Simulated camera scene')+`<div class="metric-grid">${equipmentCard('Access controller','12 / 12','secured','Door readers and lock status monitored.','Security door')}${equipmentCard('Gate monitoring','142','entries','Camera and entry barrier availability.','Main gate')}${equipmentCard('Operations room','Online','','Security supervision and alarm workstation.','Control room')}</div>`};
const twinOriginalInspector = equipmentDrawer;
equipmentDrawer = function(name) {
  if(/^Rack R-\d+/.test(name)) {
    const r = twinRackReading(Number(name.match(/R-(\d+)/)[1]));
    openDrawer(`<div class="eyebrow">DATA HALL ${twinHall} / ASSET INSPECTOR</div><h2>${esc(name)}</h2><p>${esc(currentSite().name)} / ${state.building||'DC-01'} · Simulated telemetry</p><div class="drawer-rack">${twinRackSVG(r.n,true)}</div>${status(r.hot?'critical':r.warm?'warning':'operational')}<div class="detail-list"><p>Inlet temperature<strong>${r.temperature.toFixed(1)} °C</strong></p><p>Rack load<strong>${r.load} %</strong></p><p>Power demand<strong>${r.power.toFixed(1)} kW</strong></p><p>Relative humidity<strong>${r.humidity} %RH</strong></p><p>Inlet alarm threshold<strong>30 °C</strong></p></div><h3>Temperature trend · illustrative</h3>${lineChart(1,'temperature')}<p>${r.hot?'Inlet temperature exceeds the configured threshold. Inspect containment and cooling supply.':'Rack telemetry is within its configured demonstration range.'}</p><button class="button primary" data-action="new-work">Create inspection work order</button>`);
  } else {
    twinOriginalInspector(name);
    const drawer = $('#drawer');
    drawer.innerHTML = drawer.innerHTML.replace(/(<\/h2>)/,`$1${twinScene(twinKind(name),name)}`);
  }
};
document.addEventListener('click', e=>{
  const t = e.target.closest('[data-rack-select],[data-hall-select],[data-open-hall]');
  if(!t)return;
  if(t.dataset.rackSelect){
    twinSelectedRack=Number(t.dataset.rackSelect);
    document.querySelectorAll('[data-rack-select]').forEach(el=>{const active=Number(el.dataset.rackSelect)===twinSelectedRack;el.classList.toggle('selected',active);el.setAttribute('aria-pressed',String(active))});
    $('#rack-detail').innerHTML=twinRackDetail();
  }
  if(t.dataset.hallSelect){twinHall=t.dataset.hallSelect;twinSelectedRack=12;render()}
  if(t.dataset.openHall){twinHall=t.dataset.openHall;state.tab='halls';route('building',state.site||'cairo',state.building||'DC-01')}
});
const twinOriginalClock = updateClock;
updateClock = function(){twinOriginalClock();document.body.classList.toggle('simulation-paused',state.paused)};
render();
